{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were included if they used an empirical, quantitative design, either randomised or non-randomised, such as RCTs, clinical trials, quasi-experimental studies or cohort studies; involved adolescents (≥ 10 years, according to the World Health Organization [72] definition) and/or adults (≥ 18 years) with AN, BN, BED or OSFED... either (a) compared an active psychotherapeutic intervention group (IG) in an outpatient setting with a WLCG or a no-treatment control group... reported these PROs for a minimum of two time points: (1) at or near the time of initial consultation, diagnostic workup, or study enrolment (baseline), and (2) at least once at a subsequent time point",
      "reason": "The review specifies the study designs, population (age and diagnosis), settings, and follow-up requirements (time points for PROs) used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included regardless of publication status. Both peer-reviewed and grey literature were considered. No restrictions were applied regarding publication year or language.",
      "reason": "The review explicitly states the eligibility criteria regarding publication status, publication year, and language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review did not exclude studies based on the distinction between outcomes not being measured versus not being reported; rather, it included studies with missing data (as noted in text_15), making this conditional requirement inapplicable."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "A within-group random-effects meta-analysis was performed assessing pre-post change scores of the EDE-Q Global Score (primary analysis) and EDE-Q subscales (secondary analyses).",
      "reason": "The review specifies the groups used in the synthesis (pre-post change scores of EDE-Q Global Score and subscales) and links them to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Due to equipoise concerns regarding the randomisation to WLCGs when examining validated treatments (e.g. CBT), it was not justifiable to only include RCTs. Therefore, we also searched for non-randomised studies of interventions (NRSIs), such as cohort studies, to get further insights into the natural clinical course of affected individuals while waiting for treatment.",
      "reason": "The review provides a clear rationale for the inclusion of non-randomised studies, which is a notable restriction/modification of the eligibility criteria."
    }
  ],
  "confidence": 95
}

